import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DefaultKeyedValues_removeValue_TriageGen1Test {

    private DefaultKeyedValues keyedValues;

    @Before
    public void setUp() {
        keyedValues = new DefaultKeyedValues();
    }

    @Test
    public void testRemoveValue_KeyNotFound_ThrowsException() {
        // Arrange
        keyedValues.addValue("A", 1.0);
        String missingKey = "B";

        // Act & Assert
        try {
            keyedValues.removeValue(missingKey);
            org.junit.Assert.fail("Expected UnknownKeyException to be thrown");
        } catch (UnknownKeyException e) {
            assertEquals("The key (" + missingKey + ") is not recognised.", e.getMessage());
        }
    }

    @Test
    public void testRemoveValue_KeyNotFound_IndexZero_ThrowsException() {
        // Arrange: Empty collection
        String missingKey = "AnyKey";

        // Act & Assert
        try {
            keyedValues.removeValue(missingKey);
            org.junit.Assert.fail("Expected UnknownKeyException to be thrown");
        } catch (UnknownKeyException e) {
            assertEquals("The key (" + missingKey + ") is not recognised.", e.getMessage());
        }
    }

    @Test
    public void testRemoveValue_Success() {
        // Arrange
        String key1 = "A";
        String key2 = "B";
        String key3 = "C";
        keyedValues.addValue(key1, 10.0);
        keyedValues.addValue(key2, 20.0);
        keyedValues.addValue(key3, 30.0);

        // Act
        keyedValues.removeValue(key2);

        // Assert
        assertEquals(2, keyedValues.getItemCount());
        assertEquals(key1, keyedValues.getKey(1));
        assertEquals(key3, keyedValues.getKey(2));
        assertEquals(10.0, keyedValues.getValue(1).doubleValue(), 0.001);
        assertEquals(30.0, keyedValues.getValue(2).doubleValue(), 0.001);

        // Verify key2 is truly gone
        assertEquals(-1, keyedValues.getIndex(key2)); 
    }

    @Test
    public void testRemoveValue_SingleElement_Success() {
        // Arrange
        String key = "OnlyOne";
        keyedValues.addValue(key, 5.0);

        // Act
        keyedValues.removeValue(key);

        // Assert
        assertEquals(0, keyedValues.getItemCount());
    }
}
